function mindcopyConfigPayload(){const form=$('#mindcopy-config-form'),number=name=>Number(form.elements[name].value);return {system_prompt:$('#mindcopy-system-prompt').value,user_prompt_template:$('#mindcopy-user-template').value,parameters:{temperature:number('temperature'),top_p:number('top_p'),top_k:number('top_k'),repeat_penalty:number('repeat_penalty'),max_tokens:number('max_tokens'),seed:number('seed')}}}
function renderFinalPrompt(messages){$('#mindcopy-final-prompt').textContent=(messages||[]).map(item=>`[${String(item.role).toUpperCase()}]\n${item.content}`).join('\n\n────────────────────────\n\n')||'NO PROMPT COMPILED'}
function renderMindcopyDiagnostics(data={}){$('#diag-prompt-chars').textContent=Number(data.prompt_chars||0).toLocaleString()||'—';$('#diag-first-token').textContent=data.first_token_ms!=null?`${(data.first_token_ms/1000).toFixed(1)} s`:'—';$('#diag-total-time').textContent=data.total_ms!=null?`${(data.total_ms/1000).toFixed(1)} s`:'—';$('#diag-output-speed').textContent=data.output_chars_per_second!=null?`${data.output_chars_per_second} char/s`:'—'}
function renderMindcopyConfig(data){$('#mindcopy-system-prompt').value=data.system_prompt||'';$('#mindcopy-user-template').value=data.user_prompt_template||'';const form=$('#mindcopy-config-form');Object.entries(data.parameters||{}).forEach(([name,value])=>{if(form.elements[name])form.elements[name].value=value});$('#mindcopy-template-variables').innerHTML=(data.template_variables||[]).map(variable=>`<button type="button" data-prompt-variable="${safe(variable)}">${safe(variable)}</button>`).join('');renderFinalPrompt(data.final_messages);renderMindcopyDiagnostics(data.diagnostics);const state=$('#mindcopy-config-state');state.textContent='LOCAL · SAVED';state.classList.add('saved');mindcopyConfigLoaded=true}
async function refreshMindcopyConfig(force=false){if(mindcopyConfigLoaded&&!force)return;const state=$('#mindcopy-config-state');state.textContent='LOCAL · LOADING';try{const message=$('#mindcopy-preview-message').value.trim()||'{{USER_MESSAGE}}',response=await fetch(`${API_BASE}/v1/mindcopy/config?preview_message=${encodeURIComponent(message)}`,{cache:'no-store'});if(!response.ok)throw new Error(await response.text());renderMindcopyConfig(await response.json())}catch(error){state.textContent='LOCAL · ERROR';state.classList.remove('saved')}}
async function previewMindcopyPrompt(){const button=$('#refresh-prompt-preview');button.disabled=true;try{const payload={...mindcopyConfigPayload(),message:$('#mindcopy-preview-message').value.trim()||'{{USER_MESSAGE}}'},response=await fetch(`${API_BASE}/v1/mindcopy/prompt-preview`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok)throw new Error(await response.text());const data=await response.json();renderFinalPrompt(data.final_messages);$('#diag-prompt-chars').textContent=Number(data.prompt_chars||0).toLocaleString();toast(language==='zh'?'已按当前编辑内容重新编译':'Prompt recompiled from current edits')}catch(error){toast(language==='zh'?'Prompt 编译失败，请检查模板和参数':'Prompt compilation failed')}finally{button.disabled=false}}
async function saveMindcopyConfig(event){event.preventDefault();const button=$('#save-mindcopy-config'),state=$('#mindcopy-config-state');button.disabled=true;state.textContent='LOCAL · SAVING';try{const response=await fetch(`${API_BASE}/v1/mindcopy/config`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(mindcopyConfigPayload())});if(!response.ok)throw new Error(await response.text());renderMindcopyConfig(await response.json());toast(language==='zh'?'Prompt 与推理参数已应用':'Prompt and inference parameters applied')}catch(error){state.textContent='LOCAL · ERROR';state.classList.remove('saved');toast(language==='zh'?'配置保存失败，请检查参数范围':'Could not save configuration')}finally{button.disabled=false}}
function renderIdentity(){
  const usable=contextCells.filter(c=>c.review_status==='confirmed');const basis=usable.length?usable:contextCells.filter(c=>c.review_status!=='rejected');
  const soul=basis.filter(c=>['claim','preference','decision','cognitive_shift','reflection'].includes(c.kind)),memory=basis.filter(c=>['event','decision','cognitive_shift','reflection'].includes(c.kind)),style=basis.filter(c=>c.kind==='expression'||c.kind==='claim');
  $('#soul-count').textContent=soul.length;$('#memory-count').textContent=memory.length;$('#style-count').textContent=style.length;
  $('#soul-dynamic').textContent=currentProfile?.bio||soul.slice(0,2).map(c=>c.content).join('；')||(language==='zh'?'等待基础信息与观点类 ThoughtCell。':'Waiting for profile and value-related ThoughtCells.');
  $('#memory-dynamic').textContent=memory.slice(0,2).map(c=>c.content).join('；')||(language==='zh'?'等待你确认事件、决策和转折。':'Confirm events, decisions, and transitions to build memory.');
  $('#style-dynamic').textContent=style.slice(0,2).map(c=>c.content).join('；')||(language==='zh'?'等待表达类 ThoughtCell 形成风格证据。':'Expression ThoughtCells will form style evidence.');
}
function renderReviewCard(){
  const cell=contextCells.find(c=>c.review_status==='unreviewed');if(!cell){$('#review-card').innerHTML=`<div class="empty-state" style="padding:28px">${language==='zh'?'所有 ThoughtCell 已审核':'All ThoughtCells reviewed'}</div>`;return}
  $('#review-card').innerHTML=`<div class="review-meta"><span>${safe(kindLabel(cell.kind))}</span><small>${Math.round(Number(cell.confidence||0)*100)}% confidence</small></div><blockquote>“${safe(cell.content)}”</blockquote><p>${language==='zh'?'来源':'Source'} · ${safe(cell.source_name)} · ${(cell.evidence_ids||[]).length} Evidence</p><div class="review-actions"><button class="reject" data-cell-review="rejected" data-cell-id="${safe(cell.id)}">× ${language==='zh'?'不准确':'Not accurate'}</button><button class="accept" data-cell-review="confirmed" data-cell-id="${safe(cell.id)}">✓ ${language==='zh'?'确认':'Confirm'}</button></div>`;
}
function renderContext(){renderProfile();renderCells();renderTimeline();renderIdentity();renderReviewCard()}
async function refreshContextData(){
  if(contextLoading)return;contextLoading=true;try{const [cellsResponse,profileResponse]=await Promise.all([fetch(`${API_BASE}/v1/thought-cells?limit=1000`,{cache:'no-store'}),fetch(`${API_BASE}/v1/profile`,{cache:'no-store'})]);if(!cellsResponse.ok||!profileResponse.ok)throw new Error('context unavailable');contextCells=await cellsResponse.json();currentProfile=await profileResponse.json();renderContext();if(!currentProfile&&!$('#profile-modal').classList.contains('open'))openProfile()}catch(error){}finally{contextLoading=false}
}
async function reviewCell(id,status){
  try{const response=await fetch(`${API_BASE}/v1/thought-cells/${encodeURIComponent(id)}/review`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status})});if(!response.ok)throw new Error(await response.text());const updated=await response.json();contextCells=contextCells.map(cell=>cell.id===id?updated:cell);renderContext();toast(language==='zh'?'已更新 ThoughtCell 审核状态':'ThoughtCell review updated')}catch(error){toast(language==='zh'?'审核保存失败':'Could not save review')}
}

