$('#chat-form').addEventListener('submit',async e=>{
  e.preventDefault(); const input=$('#chat-input'), value=input.value.trim(); if(!value)return;
  const user=document.createElement('div');user.className='message user';user.innerHTML=`<div><p></p></div><span class="message-avatar user-avatar">${language==='zh'?'我':'ME'}</span>`;$('p',user).textContent=value;$('#messages').append(user);input.value='';$('#messages').scrollTop=$('#messages').scrollHeight;
  const pending=document.createElement('div');pending.className='message assistant';pending.innerHTML='<span class="message-avatar">LC</span><div class="mindcopy-stream"><div class="thinking-state" role="status" aria-label="Thinking"><span class="thinking-ring"></span></div><p class="stream-answer" hidden></p></div>';$('#messages').append(pending);$('#messages').scrollTop=$('#messages').scrollHeight;
  const sendButton=$('.send',$('#chat-form'));sendButton.disabled=true;
  try{
    const response=await fetch(`${API_BASE}/v1/mindcopy/chat/stream`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:value,session_id:MINDCOPY_SESSION_ID})});if(!response.ok||!response.body)throw new Error(await response.text());
    const reader=response.body.getReader(),decoder=new TextDecoder(),answer=$('.stream-answer',pending),thinking=$('.thinking-state',pending),container=$('.mindcopy-stream',pending);let buffer='',started=false,finished=false;
    const consume=line=>{if(!line.trim())return;const event=JSON.parse(line);if(event.type==='delta'){if(!started){started=true;thinking.remove();answer.hidden=false;const cursor=document.createElement('span');cursor.className='stream-cursor';cursor.setAttribute('aria-hidden','true');container.append(cursor)}answer.textContent+=event.text;$('#messages').scrollTop=$('#messages').scrollHeight}else if(event.type==='done'){finished=true;$('.stream-cursor',container)?.remove();const citations=document.createElement('div');citations.className='citations';citations.innerHTML=`<button>${safe(event.runtime)}</button>${(event.citations||[]).slice(0,4).map(item=>`<button title="${safe(item.locator)}">${safe(item.source)} ↗</button>`).join('')}`;container.append(citations);if(event.diagnostics)renderMindcopyDiagnostics(event.diagnostics)}else if(event.type==='error'){throw new Error(event.message||'Mindcopy stream failed')}};
    while(true){const {done,value:chunk}=await reader.read();buffer+=decoder.decode(chunk||new Uint8Array(),{stream:!done});const lines=buffer.split('\n');buffer=lines.pop()||'';for(const line of lines)consume(line);if(done)break}if(buffer.trim())consume(buffer);if(!finished)throw new Error('Mindcopy stream ended unexpectedly');
  }catch(error){
    await refreshRuntime();const state=runtimeSnapshot?.llm?.state;
    $('.thinking-state',pending)?.remove();$('.stream-cursor',pending)?.remove();const answer=$('.stream-answer',pending);answer.hidden=false;answer.classList.add('stream-error');answer.textContent=cloudInferenceEnabled?String(error.message||(language==='zh'?'云端模型调用失败，请检查接口配置。':'Cloud inference failed. Check the API configuration.')):(language==='zh'?(state==='loading'||state==='starting'?'Qwen 正在载入模型，请等待运行中心显示“已运行”后重试。':state==='stopped'?'Qwen 尚未启动，请在运行中心点击“启动模型”。':String(error.message||'Mindcopy 流式回答中断，请重试。')):(state==='loading'||state==='starting'?'Qwen is still loading. Retry after Runtime shows RUNNING.':state==='stopped'?'Qwen is stopped. Start it from Runtime Center.':String(error.message||'Mindcopy stream stopped. Please retry.')));
  }finally{sendButton.disabled=false;input.focus()}
});

