const cloudModal=$('#cloud-model-modal'),cloudSettingRow=$('[data-i18n="cloudAccess"]')?.closest('.setting-row'),cloudSettingToggle=cloudSettingRow?.querySelector('input[type="checkbox"]');
const cloudPresets={openai:'https://api.openai.com/v1',deepseek:'https://api.deepseek.com/v1',openrouter:'https://openrouter.ai/api/v1',siliconflow:'https://api.siliconflow.cn/v1'};
function openCloudModel(){cloudModal.classList.add('open');cloudModal.setAttribute('aria-hidden','false');refreshCloudModel();refreshMemoryCandidates()}
function closeCloudModel(){cloudModal.classList.remove('open');cloudModal.setAttribute('aria-hidden','true')}
async function refreshCloudModel(){
  try{
    const [configResponse,memoryResponse]=await Promise.all([fetch(`${API_BASE}/v1/cloud-model/config`,{cache:'no-store'}),fetch(`${API_BASE}/v1/memory/summary`,{cache:'no-store'})]);
    if(!configResponse.ok||!memoryResponse.ok)throw new Error('configuration unavailable');
    const config=await configResponse.json(),memory=await memoryResponse.json();cloudInferenceEnabled=Boolean(config.enabled);$('#cloud-enabled').checked=cloudInferenceEnabled;$('#cloud-provider').value=config.provider||'openai-compatible';$('#cloud-base-url').value=config.base_url||'';$('#cloud-model').value=config.model||'';$('#cloud-timeout').value=config.timeout_seconds||120;cloudSettingToggle&&(cloudSettingToggle.checked=cloudInferenceEnabled);$('#cloud-config-state').textContent=`${cloudInferenceEnabled?'CLOUD ON':'CLOUD OFF'} · ${config.api_key_configured?'KEY IN MEMORY':'NO KEY'}`;$('#cloud-config-state').classList.toggle('cloud-configured',cloudInferenceEnabled);$('#memory-session-count').textContent=memory.sessions??0;$('#memory-pending-count').textContent=memory.unreviewed_count??0;$('#memory-confirmed-count').textContent=memory.confirmed_count??0;
  }catch(error){$('#cloud-config-state').textContent='BACKEND OFFLINE'}
}
async function refreshMemoryCandidates(){try{const response=await fetch(`${API_BASE}/v1/memory/candidates?status=unreviewed&limit=20`,{cache:'no-store'});if(!response.ok)throw new Error();const items=await response.json();$('#memory-candidate-list').innerHTML=items.length?items.map(item=>`<div class="memory-candidate"><p>${safe(item.content)}<small>${safe(item.kind)} · ${new Date(item.created_at).toLocaleString()}</small></p><div><button type="button" data-memory-review="confirmed" data-memory-id="${safe(item.id)}">确认</button><button type="button" class="reject" data-memory-review="rejected" data-memory-id="${safe(item.id)}">排除</button></div></div>`).join(''):'<small>暂无待确认记忆。对话中的长期偏好、决定和经历会先出现在这里。</small>'}catch(error){$('#memory-candidate-list').innerHTML='<small>记忆候选暂时无法读取。</small>'}}
$('#memory-candidate-list').addEventListener('click',async event=>{const button=event.target.closest('[data-memory-review]');if(!button)return;button.disabled=true;try{const response=await fetch(`${API_BASE}/v1/memory/candidates/${encodeURIComponent(button.dataset.memoryId)}/review`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:button.dataset.memoryReview})});if(!response.ok)throw new Error();await Promise.all([refreshMemoryCandidates(),refreshCloudModel()]);toast(button.dataset.memoryReview==='confirmed'?'已写入确认记忆':'已排除这条候选记忆')}catch(error){toast('记忆审核保存失败')}finally{button.disabled=false}});
$('#cloud-model-form').addEventListener('submit',async event=>{event.preventDefault();const payload={enabled:$('#cloud-enabled').checked,provider:$('#cloud-provider').value,base_url:$('#cloud-base-url').value.trim(),model:$('#cloud-model').value.trim(),api_key:$('#cloud-api-key').value.trim(),timeout_seconds:Number($('#cloud-timeout').value)||120};const button=$('button[type="submit"]',event.currentTarget);button.disabled=true;try{const response=await fetch(`${API_BASE}/v1/cloud-model/config`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await response.json();if(!response.ok)throw new Error(data.detail||'Could not save cloud model');$('#cloud-api-key').value='';await refreshCloudModel();toast(language==='zh'?(payload.enabled?'云端最终推理已开启，记忆仍在本地':'已切回本地模型'):(payload.enabled?'Cloud inference enabled; memory stays local':'Switched back to local model'));closeCloudModel()}catch(error){toast(String(error.message||error))}finally{button.disabled=false}});
$('#cloud-provider').addEventListener('change',event=>{const preset=cloudPresets[event.target.value];if(preset)$('#cloud-base-url').value=preset});$('#close-cloud-model').addEventListener('click',closeCloudModel);cloudModal.addEventListener('click',event=>{if(event.target===cloudModal)closeCloudModel()});if(cloudSettingRow){cloudSettingRow.tabIndex=0;cloudSettingRow.setAttribute('role','button');cloudSettingRow.addEventListener('click',event=>{event.preventDefault();openCloudModel()});cloudSettingRow.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();openCloudModel()}})}

applyLanguage(language);
